"""Beats (voice seconds after the quiz pause stretch) from whisper word indices -> beats.json; captions with per-word times -> caps_<lang>.json.
Captions use the script's own spelling; each sentence's words are spread over its spoken span by length."""
import json
IDX = {'ru': dict(s1=0, s1b=3, fr=7, sa=10, bal=11, ent=13, len=24, narrow=29, mid=34, uzy=43, uzyw=46, slow=51, salt=56, ans=61, ili=63, src=65, china=71, p80c=72, p80=74,
                  west=80, fresh=86, east=91, sun=98, saltst=102, mix=107, salty=113, threat=120, fields=123, aral=132, aralw=139, quiz=141, qq=143,
                  o1=152, o2=153, o3=155, right=156, cta=159),
       'kk': dict(s1=0, s1b=4, fr=7, sa=10, bal=11, ent=13, len=23, narrow=29, mid=33, uzy=40, uzyw=43, slow=49, salt=55, ans=61, ili=62, src=64, china=65, p80c=69, p80=73,
                  west=78, fresh=83, east=88, sun=94, saltst=98, mix=102, salty=107, threat=113, fields=117, aral=124, aralw=126, quiz=131, qq=133,
                  o1=139, o2=140, o3=142, right=143, cta=145)}
S = {'ru': [('s1', 'Это одно озеро.'), ('s1b', 'Но одна его половина пресная, а другая — солёная.'), ('bal', 'Это Балхаш.'),
            ('ent', 'На ЕНТ про него спрашивают часто, и многие ошибаются именно здесь.'), ('len', 'Длина Балхаша больше 600 километров.'),
            ('narrow', 'Но он узкий и мелкий.'), ('mid', 'А посередине его делит на две части узкий пролив.'), ('uzy', 'Это пролив Узынарал, шириной всего 3–4 километра.'),
            ('slow', 'Вода через него проходит медленно.'), ('salt', 'Но при чём тут соль?'), ('ans', 'Ответ — река Или.'), ('src', 'Она начинается в Восточном Тянь-Шане в Китае'),
            ('p80c', 'и приносит около 80% всей воды Балхаша.'), ('west', 'Впадает она именно в западную часть.'), ('fresh', 'Поэтому на западе вода пресная.'),
            ('east', 'А на восток речной воды доходит мало.'), ('sun', 'Жаркое солнце испаряет воду,'), ('saltst', 'а соль остаётся в озере.'),
            ('mix', 'Узкий пролив не даёт водам смешаться.'), ('salty', 'Поэтому восточная часть в несколько раз солонее.'), ('threat', 'Но есть угроза.'),
            ('fields', 'По пути воду Или забирают поля и водохранилища.'), ('aral', 'Учёные предупреждают: Балхаш не должен повторить судьбу Арала.'),
            ('quiz', 'Вопрос ЕНТ.'), ('qq', 'Какая река приносит в Балхаш больше всего воды?'), ('o1', 'Шу, Или или Иртыш?'), ('right', 'Правильно: Или.')],
     'kk': [('s1', 'Бұл — бір ғана көл.'), ('s1b', 'Бірақ бір жартысы — тұщы, екінші жартысы — тұзды.'), ('bal', 'Бұл — Балқаш.'),
            ('ent', 'ҰБТ-да оны жиі сұрайды, ал көп оқушы осы жерде қателеседі.'), ('len', 'Балқаш ұзындығы 600 шақырымнан асады.'),
            ('narrow', 'Бірақ ені тар, тайыз.'), ('mid', 'Ал ортасында оны жіңішке бұғаз екіге бөледі.'), ('uzy', 'Бұл — Ұзынарал бұғазы, ені бар болғаны 3–4 шақырым.'),
            ('slow', 'Су ол арқылы баяу ғана өтеді.'), ('salt', 'Бірақ мұның тұзға қандай қатысы бар?'), ('ans', 'Жауабы — Іле өзенінде.'), ('src', 'Іле Қытайдағы Шығыс Тянь-Шаньнан басталады'),
            ('p80c', 'және Балқашқа келетін судың шамамен 80%-ын әкеледі.'), ('west', 'Ол дәл батыс бөлігіне құяды.'), ('fresh', 'Сондықтан батыс жақтағы су тұщы.'),
            ('east', 'Ал шығысқа өзен суы аз жетеді.'), ('sun', 'Ыстық күн суды буландырады,'), ('saltst', 'ал тұз көлде қалады.'),
            ('mix', 'Тар бұғаз екі суды араластырмайды.'), ('salty', 'Сондықтан шығыс бөлігі бірнеше есе тұздырақ.'), ('threat', 'Бірақ бір қауіп бар.'),
            ('fields', 'Іле суын жолда егістік пен су қоймалары көп алады.'), ('aral', 'Ғалымдар Балқашқа Аралдың тағдыры қайталанбауы керек деп ескертеді.'),
            ('quiz', 'ҰБТ сұрағы.'), ('qq', 'Балқашқа ең көп су әкелетін өзен?'), ('o1', 'Шу, Іле әлде Ертіс?'), ('right', 'Дұрыс: Іле.')]}
out = {}
for L in IDX:
    W = json.load(open(f'words_{L}_x.json')); B = {k: W[i][0] for k, i in IDX[L].items()}; B['vend'] = W[-1][1]; out[L] = B
    caps = []; seq = S[L] + [('cta', None)]
    for (k, s), (k2, _) in zip(seq, seq[1:]):
        t0, t1 = B[k], B[k2]
        end = max([w[1] for w in W if t0 - .05 <= w[0] < t1 - .05] or [t1 - .3])
        words = s.replace(' —', '').split(' '); tot = sum(len(w) + 2 for w in words); t = t0; tw = []
        for w in words: d = (end - t0) * (len(w) + 2) / tot; tw.append([w, round(t, 2), round(t + d, 2)]); t += d
        cur = []
        for w in tw:
            cur.append(w)
            if len(cur) == 3 or (len(cur) == 2 and len(' '.join(c[0] for c in cur)) > 16) or w[0][-1] in ',.?:':
                caps.append([cur[0][1], cur[-1][2], cur]); cur = []
        if cur: caps.append([cur[0][1], cur[-1][2], cur])
    json.dump(caps, open(f'caps_{L}.json', 'w'), ensure_ascii=False); print(L, len(caps), B['vend'])
json.dump(out, open('beats.json', 'w'), indent=0)
